fn encode_shift(s: Vec<char>) -> Vec<char> {
    // We know each `c` is in 'a'..='z', so we can safely cast to `u8`.
    // 'a' as u8 is 97. We subtract that to get a 0–25 range,
    // add 5, take mod 26, then add 97 back and cast to char.
    s.into_iter()
     .map(|c| {
         let base = b'a';
         let shifted = ((c as u8 - base + 5) % 26) + base;
         shifted as char
     })
     .collect()
}

fn main() {
    let examples = vec![
        vec!['a', 'b', 'c'],        // "abc" -> "fgh"
        vec!['v', 'w', 'x', 'y', 'z'], // "vwxyz" -> "abcde"
        vec![],                     // empty -> empty
    ];

    for s in examples {
        let encoded: String = encode_shift(s.clone()).into_iter().collect();
        let original: String = s.into_iter().collect();
        println!("{} -> {}", original, encoded);
    }
}